"""Clean-room CoreCommands mixin — methods inherited by Redis and Pipeline.

In real redis, `pipe.set()` resolves to this mixin; async-doctor must key
off the *receiver type* (Pipeline), not this defining class.
"""


class CoreCommands:
    def get(self, name, *args, **kwargs):
        pass

    def set(self, name, value, *args, **kwargs):
        pass

    def delete(self, *names):
        pass

    def execute_command(self, *args, **kwargs):
        pass


class AsyncCoreCommands:
    async def get(self, name, *args, **kwargs):
        pass

    async def set(self, name, value, *args, **kwargs):
        pass

    async def delete(self, *names):
        pass

    async def execute_command(self, *args, **kwargs):
        pass
